{
  "q1_human_microarray_expression_profiling": {
    "answer": "Yes",
    "evidence": "Study type: transcription profiling by array; Affymetrix U133A chips; Organism: Homo sapiens; Assay by Molecule: RNA assay. Description: RNA was extracted from 110 patients ... Gene expression was assessed using Affymetrix U133A chips.",
    "justification": "Dataset uses human samples and Affymetrix microarray (U133A) to profile RNA expression in circulating leukocytes."
  },
  "q2_target_disease": {
    "answer": "No",
    "evidence": "Title and description focus on coronary artery disease (CAD); references to CAD index (CADi), coronary angiography, and identifying patients with coronary artery disease.",
    "justification": "Study investigates coronary artery disease, not amyotrophic lateral sclerosis or frontotemporal dementia."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Description: 'Gene expression profile in circulating leukocytes' and 'peripheral leukocyte gene expression pattern'; Organism part not listed as brain/CNS.",
    "justification": "Samples are peripheral blood leukocytes, not human brain/CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description: 'RNA was extracted from 110 patients with CAD ... and from 112 ... controls'; no mention of cell lines or in vitro disease models.",
    "justification": "Samples are patient-derived peripheral blood specimens, not patient-derived cell lines or experimental disease models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "Description: RNA extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); study listed as 'parallel group design'.",
    "justification": "Study compares cases (CAD) versus matched controls, consistent with a case/control design."
  },
  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Samples are circulating/peripheral leukocytes (blood), not brain regions.",
    "justification": "No CNS regions were sampled; the sampled tissue (blood) is not a brain region and therefore not relevant to ALS-FTD neurodegeneration."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Technology: Array assay; Affymetrix U133A microarrays used (microarray expression profiling).",
    "justification": "Platform is microarray, which is compatible with the inclusion criterion (not RNA-seq or proteomics)."
  },
  "q8_inclusion_justification": {
    "justification": "Although this is a human microarray study with a case/control design, it investigates coronary artery disease using peripheral blood leukocytes rather than ALS-FTD and does not include CNS tissue. Therefore it fails the disease (ALS-FTD) and tissue (CNS) inclusion criteria and should be excluded."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

